entries[58455] = { ["name"] = "Arkane Explosion", ["text"] = "120 Mana\nSofort\nLässt eine Druckwelle aus Magie entstehen und fügt in der Nähe befindlichen Feinden 648 to 752 Arkanschaden zu." }
