entries[58459] = { ["name"] = "Durchbohren", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFügt einem Gegner 12 Sek. lang alle 3 Sek. 250 körperlichen Schaden zu." }
entries[58460] = { ["name"] = "Brutaler Stoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 150% Waffenschaden." }
entries[58461] = { ["name"] = "Rüstung zerreißen", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nHackt auf die Rüstung eines Feindes ein und verringert sie um 10% pro Einsatz von 'Rüstung zerreißen'. Kann bis zu 5-mal angewendet werden. Hält 20 Sek. lang." }
entries[58462] = { ["name"] = "Arkanschlag", ["text"] = "195 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nÜberzieht einen Feind mit Arkanmagie und verursacht 833 to 967 Arkanschaden. Jedes Mal, wenn Ihr 'Arkanschlag' wirkt, verringert sich die Zauberzeit. Dieser Effekt ist bis zu 5-mal stapelbar und hält 8 Sek. lang an." }
