entries[58464] = { ["name"] = "Eisketten", ["text"] = "120 Mana 30 Meter Reichweite\nSofort\nSchlingt eisige Ketten um das Ziel, die es 4 Sek. lang am Platz festhalten." }
entries[58465] = { ["name"] = "Gigantisches Festmahl", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nRichtet für Eure Gruppe ein großartiges Festmahl her! Stellt im Verlauf von 30 Sek. 22500 Gesundheit und 19200 Mana wieder her. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr größer." }
