entries[58470] = { ["name"] = "Taktisches Blinzeln", ["text"] = "40 Meter Reichweite\nSofort\nTeleportiert den Zaubernden hinter das Ziel. Befreit den Zaubernden auch von jeglichen Fesseln." }
