entries[58492] = { ["name"] = "Wilder Titanring", ["text"] = "Wirken in 12.5 sek.\nTools: Juweliersset\nReagenzien:\nTitanbarren (4), Äonenfeuer (4)\nWilder Titanring\nWird beim Anlegen gebunden\nEinzigartig anlegbarFinger\n+48 Ausdauer\n\nRoter Sockel\nSockelbonus: +4 Kritische Trefferwertung\n\n78\nAnlegen: Erhöht die kritische Trefferwertung um 33.\nAnlegen: Erhöht Eure Abhärtungswertung um 32.\nAnlegen: Erhöht die Angriffskraft um 32." }
