entries[58504] = { ["name"] = "Peinigender Schlag", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht beim Ziel 100% Waffenschaden und Schmerzen, und der verursachte Schaden erhöht sich 5 Sek. lang um 20%." }
