entries[59265] = { ["name"] = "Tödliche Wunde", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht 150% Waffenschaden beim Feind und verwundet ihn, verringert außerdem die Wirksamkeit jeglicher Heilung 20 Sek. lang um 5%." }
entries[59266] = { ["name"] = "Wasserschusssalve", ["text"] = "50 Mana 35 Meter Reichweite\nWirken in 1.5 sek.\nSchießt Wasser auf alle Feinde in einem Umkreis von 35 Metern und verursacht Frostschaden." }
entries[59267] = { ["name"] = "Welkendes Gebrüll", ["text"] = "Sofort\nVerursacht bei umstehenden Feinden 4000 Schaden und verringert ihre Gesundheit um 1000. Bis zu 50-mal stapelbar. Hält 30 Sek. lang an." }
entries[59268] = { ["name"] = "Durchbohren", ["text"] = "60 Meter Reichweite\nSofort\nWirft einen Speer auf das Ziel, verursacht 3770 to 4230 Schaden und alle 3 Sek. zusätzlich 3000 Schaden. Hält 9 Sek. lang an." }
entries[59269] = { ["name"] = "Biss des Fleischfressers", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 15 Sek. lang alle 3 Sek. körperlichen Schaden zu." }
